package pl.atrop.powerguard.bcknd.shared.infrastructure.repository.db.sqldb.repositories;
import jakarta.enterprise.context.ApplicationScoped; import jakarta.inject.Inject; import jakarta.transaction.Transactional; import java.util.*; import pl.atrop.powerguard.bcknd.meter.domain.*; import pl.atrop.powerguard.bcknd.shared.infrastructure.repository.db.sqldb.boundaries.*; import pl.atrop.powerguard.bcknd.shared.infrastructure.repository.db.sqldb.entities.*;
@ApplicationScoped public class SqlMetersRepository implements MetersRepository {
 @Inject MetersBoundary meters; @Inject AlarmRulesBoundary rules; @Inject EdgesBoundary edges; @Inject SitesBoundary sites; @Inject ClientsBoundary clients;
 public List<MeterConfiguration> findAll(){return meters.findAllOrdered().stream().map(this::toDomain).toList();} public Optional<MeterConfiguration> findById(Integer id){return Optional.ofNullable(meters.find(id)).map(this::toDomain);}
 public Optional<MeterConfiguration> findByIdentity(String clientId,String siteId,String edgeId,String key){var c=clients.findByClientId(clientId);if(c.isEmpty())return Optional.empty();var s=sites.findByClientFkAndSiteId(c.get().getId(),siteId);if(s.isEmpty())return Optional.empty();var e=edges.findBySiteFkAndEdgeId(s.get().getId(),edgeId);return e.flatMap(x->meters.findByEdgeFkAndUniqueKey(x.getId(),key)).map(this::toDomain);}
 public Optional<MeterConfiguration> findByLegacyIdentity(String siteId,String edgeId,String key){var matches=findAll().stream().filter(m->siteId.equals(m.siteId())&&edgeId.equals(m.edgeId())&&key.equals(m.uniqueKey())).toList();return matches.size()==1?Optional.of(matches.get(0)):Optional.empty();}
 public boolean uniqueKeyExistsForOtherMeter(Long edgePk,String key,Integer id){return meters.uniqueKeyExistsForOtherMeter(edgePk,key,id);}
 @Transactional public MeterConfiguration create(MeterConfiguration m){int order=meters.nextDisplayOrder(m.edgePk());Meters e=meters.save(new Meters(m.edgePk(),m.uniqueKey(),m.name(),m.enabled(),order));rules.save(new AlarmRules(e.getId(),m.instantaneousAlarmOnKw(),m.instantaneousAlarmOffKw(),m.quarterHourAlarmOnKw(),m.quarterHourAlarmOffKw()));return toDomain(e);}
 @Transactional public MeterConfiguration update(MeterConfiguration m){Meters e=meters.find(m.id());e.setEdgeFk(m.edgePk());e.setUniqueKey(m.uniqueKey());e.setName(m.name());e.setEnabled(m.enabled());meters.save(e);AlarmRules a=rules.findByMeterId(e.getId()).orElseGet(()->new AlarmRules(e.getId(),null,null,null,null));a.setInstantaneousAlarmOnKw(m.instantaneousAlarmOnKw());a.setInstantaneousAlarmOffKw(m.instantaneousAlarmOffKw());a.setQuarterHourAlarmOnKw(m.quarterHourAlarmOnKw());a.setQuarterHourAlarmOffKw(m.quarterHourAlarmOffKw());rules.save(a);return toDomain(e);}
 @Transactional public boolean moveUp(Integer id){return move(id,-1);} @Transactional public boolean moveDown(Integer id){return move(id,1);} private boolean move(Integer id,int d){Meters selected=meters.find(id);if(selected==null)return false;List<Meters> ordered=meters.findAllOrdered().stream().filter(m->Objects.equals(m.getEdgeFk(),selected.getEdgeFk())).toList();int idx=-1;for(int i=0;i<ordered.size();i++)if(Objects.equals(ordered.get(i).getId(),id)){idx=i;break;}int other=idx+d;if(idx<0||other<0||other>=ordered.size())return false;Meters a=ordered.get(idx),b=ordered.get(other);int ao=a.getDisplayOrder();a.setDisplayOrder(b.getDisplayOrder());b.setDisplayOrder(ao);meters.save(a);meters.save(b);return true;} @Transactional public void delete(Integer id){rules.deleteByMeterId(id);meters.deleteById(id);}
 private MeterConfiguration toDomain(Meters m){Edges e=edges.find(m.getEdgeFk());Sites s=e==null?null:sites.find(e.getSiteFk());Clients c=s==null?null:clients.find(s.getClientFk());AlarmRules a=rules.findByMeterId(m.getId()).orElse(null);return new MeterConfiguration(m.getId(),s==null?null:s.getId(),e==null?null:e.getId(),c==null?"":c.getClientId(),c==null?"":c.getName(),s==null?"":s.getSiteId(),s==null?"":s.getName(),e==null?"":e.getEdgeId(),m.getUniqueKey(),m.getName(),a==null?null:a.getInstantaneousAlarmOnKw(),a==null?null:a.getInstantaneousAlarmOffKw(),a==null?null:a.getQuarterHourAlarmOnKw(),a==null?null:a.getQuarterHourAlarmOffKw(),m.isEnabled(),m.getDisplayOrder());}
}
